1	// HandoffController glues CsrTrigger and StateDrain. Given a retired PC,
2	// decides whether to drain state and returns the populated hybrid_state_v1
3	// if so. Pure-logic; no SystemC.
4	
5	#include "hybrid/abstract_command.hpp"
6	#include "hybrid/csr_trigger.hpp"
7	#include "hybrid/handoff_controller.hpp"
