140	  for (int i = 0; i < 7; ++i) {
141	    const auto state = h.on_retire(0x1000 + 4u * static_cast<unsigned>(i));
142	    CHECK_FALSE(state.has_value());
143	  }
144	
145	  // Checkpoints at retires 3 and 6 (7th retire is below the next target).
146	  REQUIRE(ks.size() == 2);
