// ---- cosim explicit targets (cosim_redesign F3) ----

TEST_CASE("HandoffController cosim targets: sink fires at each target; the "
          "LAST target finishes the run instead of resuming")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_gpr(12)] = 42;
  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000010;

  hybrid::CsrTrigger trigger;  // no EXIT anywhere
  hybrid::HandoffController h(std::move(trigger), bus);

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64;
  input.priv    = 3;
  h.set_passthrough_input(input);

  std::vector<uint64_t> ks;
  h.enable_cosim_targets({2, 5}, [&](const hybrid_state_v1& st, uint64_t k) {
    ks.push_back(k);
    CHECK(st.gpr[12] == 42u);
  });

  // Retires 1..4: no exit. Target 2 drains checkpoint 1 and resumes.
  for (int i = 0; i < 4; ++i)
    CHECK_FALSE(h.on_retire(0x1000 + 4u * static_cast<unsigned>(i)).has_value());

  // Retire 5 = last target: record 2 goes to the sink AND the run finishes
  // (state returned; simulator writes <handoff_out> and exits 200).
  const auto final_state = h.on_retire(0x1010);
  REQUIRE(final_state.has_value());
  CHECK(final_state->gpr[12] == 42u);

  REQUIRE(ks.size() == 2);
  CHECK(ks[0] == 1u);
  CHECK(ks[1] == 2u);

  // Only the FIRST checkpoint resumed the hart; the final drain leaves it
  // halted (the run ends there).
  std::size_t resumes = 0;
  for (const auto& op : bus.ops) {
    const bool resume_write = op.kind == hybrid::test::DmiOp::Kind::Write
      && op.reg == RD::kDmcontrol
      && (op.value & RD::kDmcontrolResumereq) != 0u;
    if (resume_write) ++resumes;
  }
  CHECK(resumes == 1u);
}

TEST_CASE("HandoffController cosim targets: retires past the last target "
          "are unreachable -- but an EXIT before it still wins")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000048;

  hybrid::CsrTrigger trigger;
  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);

  hybrid::HandoffController h(std::move(trigger), bus);

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64;
  input.priv    = 3;
  h.set_passthrough_input(input);

  std::size_t sink_calls = 0;
  h.enable_cosim_targets({10},
                         [&](const hybrid_state_v1&, uint64_t) { ++sink_calls; });

  CHECK_FALSE(h.on_retire(0x1000).has_value());
  const auto state = h.on_retire(0x80000044);  // EXIT at retire 2
  REQUIRE(state.has_value());
  CHECK(sink_calls == 0u);
}

TEST_CASE("HandoffController cosim targets: empty target list throws")
{
  RecordingBus bus;
  hybrid::CsrTrigger trigger;
  hybrid::HandoffController h(std::move(trigger), bus);

  CHECK_THROWS_AS(
    h.enable_cosim_targets({}, [](const hybrid_state_v1&, uint64_t) {}),
    std::runtime_error);
}

TEST_CASE("HandoffController cosim: disabled by default -- plain retires stay "
          "silent even with passthrough set")

