17	#include <functional>
18	#include <optional>
19	#include <stdexcept>
20	#include <utility>
21	#include <vector>
22	
23	namespace hybrid
24	{
25	
26	template<typename Trigger, typename Observer = NullObserver>
27	class HandoffController
28	{
29	public:
30	  HandoffController(Trigger trigger, DmiBus& bus)
31	      : trigger_{std::move(trigger)}, drain_{bus}
32	  {}
33	
34	  HandoffController(Trigger trigger, DmiBus& bus, Observer observer)
35	      : trigger_{std::move(trigger)},
36	        drain_{bus},
37	        observer_{std::move(observer)}
38	  {}
39	
40	  // Snapshot of the QEMU 1 input state. When set, drain merges FP/CSR/V
41	  // fields from the snapshot into the freshly drained GPRs+PC, avoiding
42	  // a per-field DM Abstract Command on every handoff.
43	  void set_passthrough_input(hybrid_state_v1 input)
44	  {
45	    passthrough_ = input;
46	  }
47	
48	  // cosim_roi F2: every `interval` retires, drain a resumable checkpoint and
49	  // hand it to `sink` (k counts from 1). The caller writes the numbered file;
50	  // the hart keeps running. Requires the passthrough snapshot (checkpoints
51	  // reuse drain_checkpoint, which needs the QEMU1 flags/CSR slots).
52	  using CosimSink = std::function<void(const hybrid_state_v1&, uint64_t)>;
53	  void enable_cosim(uint64_t interval, CosimSink sink)
54	  {
55	    cosim_interval_ = interval;
56	    cosim_next_     = interval;
57	    cosim_sink_     = std::move(sink);
58	  }
59	
60	  // cosim_redesign F3: explicit ascending retire targets instead of an
61	  // interval. Each target drains a checkpoint to `sink`; the LAST target
62	  // FINISHES the run -- its drain is also returned from on_retire so the
63	  // caller writes the final state file and exits, without waiting for the
64	  // exit trigger (which still wins if it fires earlier).
65	  void enable_cosim_targets(std::vector<uint64_t> targets, CosimSink sink)
66	  {
67	    if (targets.empty())
68	      throw std::runtime_error(
69	        "HandoffController cosim: explicit target list must not be empty");
70	    cosim_targets_ = std::move(targets);
71	    cosim_next_    = cosim_targets_.front();
72	    cosim_sink_    = std::move(sink);
73	  }
74	
75	  // Read-only view of the underlying trigger. Used by the ROI kanata-gate
76	  // derivation, which needs to read scanned EXIT PCs without consuming them.
77	  auto trigger() const -> const Trigger& { return trigger_; }
78	
79	  // Read-only view of the observer slot. F16 (StateDrain) reads the warmup
80	  // snapshot from here when copying into the ABI struct.
81	  auto observer() const -> const Observer& { return observer_; }
82	  auto observer() -> Observer& { return observer_; }
83	
84	  auto on_retire(uint64_t pc) -> std::optional<hybrid_state_v1>
85	  {
86	    if constexpr (requires { trigger_.observe_commit(); }) {
87	      trigger_.observe_commit();
88	    }
89	    if constexpr (requires { observer_.observe_commit(); }) {
90	      observer_.observe_commit();
91	    }
92	    const auto hit = trigger_.lookup(pc);
93	    // Only EXIT drains; entry is QEMU's job, vsim ignores ENTER. Every
94	    // non-exit retire advances the cosim checkpoint counter instead.
95	    if (!hit || hit->kind != HYBRID_HANDOFF_EXIT)
96	      return maybe_cosim_checkpoint();
97	    push_warmup_snapshot();
98	    if (passthrough_) return drain_.drain_with_passthrough(*passthrough_);
99	    return drain_.drain();
100	  }
101	
102	private:
103	  // F16: push warmup snapshot into the drain right before it runs so the
104	  // returned state carries mcycle_at_measure_start / minstret_at_measure_start.
105	  // The if-constexpr branch compiles away for NullObserver (no accessors).
106	  void push_warmup_snapshot()
107	  {
108	    if constexpr (requires { observer_.mcycle_at_measure_start(); }) {
109	      drain_.set_warmup_snapshot(observer_.mcycle_at_measure_start(),
110	                                 observer_.minstret_at_measure_start());
111	    }
112	  }
113	
114	  // Monotonic target (not modulo) so the slack retires that commit while a
115	  // checkpoint's haltreq propagates are simply absorbed into the next window.
116	  // Returns a state only in targets mode at the LAST target (run finishes).
117	  auto maybe_cosim_checkpoint() -> std::optional<hybrid_state_v1>
118	  {
119	    const bool targets_mode = !cosim_targets_.empty();
120	    const bool targets_done = targets_mode
121	      && cosim_target_idx_ >= cosim_targets_.size();
122	    if ((cosim_interval_ == 0 && !targets_mode) || targets_done)
123	      return std::nullopt;
124	    if (++cosim_retires_ < cosim_next_) return std::nullopt;
125	    if (!passthrough_)
126	      throw std::runtime_error(
127	        "HandoffController cosim: checkpoints require the QEMU passthrough "
128	        "snapshot (set_passthrough_input)");
129	    push_warmup_snapshot();
130	
131	    if (targets_mode && cosim_target_idx_ + 1 == cosim_targets_.size()) {
132	      // Last explicit target: drain WITHOUT resuming -- this record both
133	      // goes to the sink and ends the run as the final state.
134	      ++cosim_target_idx_;
135	      const auto state = drain_.drain_with_passthrough(*passthrough_);
136	      cosim_sink_(state, ++cosim_count_);
137	      return state;
138	    }
139	
140	    if (targets_mode)
141	      cosim_next_ = cosim_targets_[++cosim_target_idx_];
142	    else
143	      cosim_next_ += cosim_interval_;
144	    cosim_sink_(drain_.drain_checkpoint(*passthrough_), ++cosim_count_);
145	    return std::nullopt;
146	  }
147	
148	  Trigger trigger_;
149	  StateDrain drain_;
150	  Observer observer_{};
151	  std::optional<hybrid_state_v1> passthrough_;
152	  uint64_t cosim_interval_ = 0;  // 0 + empty targets = cosim disabled
153	  std::vector<uint64_t> cosim_targets_;
154	  std::size_t cosim_target_idx_ = 0;
155	  uint64_t cosim_retires_  = 0;
156	  uint64_t cosim_next_     = 0;
157	  uint64_t cosim_count_    = 0;
158	  CosimSink cosim_sink_;
159	};
160	
