// cosim_redesign F3: parse the --hybrid-cosim-at colon-separated retire
// targets. Must be strictly ascending, each >= 1.
static auto parse_cosim_targets(const std::string& spec)
  -> std::vector<uint64_t>
{
  std::vector<uint64_t> targets;
  std::size_t pos = 0;
  while (pos <= spec.size()) {
    const auto colon = spec.find(':', pos);
    const auto tok = spec.substr(
      pos, colon == std::string::npos ? std::string::npos : colon - pos);
    try {
      std::size_t used = 0;
      const uint64_t v = std::stoull(tok, &used, 0);
      if (used != tok.size() || v == 0) throw std::invalid_argument(tok);
      targets.push_back(v);
    } catch (...) {
      throw std::runtime_error("--hybrid-cosim-at: bad target '" + tok
                               + "' in '" + spec + "'");
    }
    if (colon == std::string::npos) break;
    pos = colon + 1;
  }
  for (std::size_t i = 1; i < targets.size(); ++i)
    if (targets[i] <= targets[i - 1])
      throw std::runtime_error(
        "--hybrid-cosim-at: targets must be strictly ascending: " + spec);
  return targets;
}

