37	    warmup_mcycle_   = mcycle;
38	    warmup_minstret_ = minstret;
39	  }
40	
41	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
42	  // drain_with_passthrough when the QEMU 1 snapshot is available.
43	  auto drain() -> hybrid_state_v1
44	  {
45	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
46	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
47	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
48	                   "StateDrain halt");
49	
50	    hybrid_state_v1 state{};
51	    state.magic   = HYBRID_STATE_MAGIC;
52	    state.version = HYBRID_STATE_VERSION;
53	    state.flags   = HYBRID_FLAG_RV64;
54	    // L6: dcsr.prv holds the privilege the hart was in when the halt landed.
55	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
56	                                  "StateDrain DCSR") & 0x3u;
57	
58	    for (uint16_t i = 1; i < 32; ++i)
59	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
60	
61	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
62	    state.mcycle_at_measure_start   = warmup_mcycle_;
63	    state.minstret_at_measure_start = warmup_minstret_;
64	    return state;
65	  }
66	
67	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
68	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
69	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
70	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
71	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
72	  // and vreg remain pass-through (read-only / too large for DM).
73	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
74	  // contribution would otherwise be discarded as the passthrough preserves
75	  // QEMU1's pre-handoff value.
76	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
77	  {
78	    auto state       = input;
79	    const auto fresh = drain();
80	    std::copy(std::begin(fresh.gpr) + 1, std::end(fresh.gpr),
81	              std::begin(state.gpr) + 1);
82	    state.pc   = fresh.pc;
83	    state.priv = fresh.priv;  // L6: privilege at the exit halt, not QEMU1's
84	
85	    if (input.flags & HYBRID_FLAG_FP) {
