88	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
89	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
90	    }
91	
92	    if (input.flags & HYBRID_FLAG_V) {
93	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
94	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
95	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
96	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
97	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
98	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
99	    }
100	
101	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
102	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
103	
104	    // V data regfile: dump v0..v31 to the shared scratch region via the
105	    // Program Buffer LAST -- after every architectural read above -- so the
106	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
