// ELF symbol resolution for pc-trigger boundaries (F9).
//
// pc mode switches QEMU <-> vsim at two PCs. Either boundary may be a
// "0x"-prefixed hex address (used verbatim) OR a symbol defined in the ELF
// (resolved against its .symtab). This decouples the switch points from the
// workload source -- any function can bound the ROI, with no planted markers.
//
// C++ port of tests/lib/roi.sh:resolve_pc, reading the ELF .symtab directly via
// <elf.h> rather than shelling out to `nm`.
#ifndef ANDES_SIM_ELF_SYMS_HPP
#define ANDES_SIM_ELF_SYMS_HPP

#include <string>

namespace andes_sim {

// Resolve a pc-mode boundary to a bare hex address string (no "0x" prefix).
//   "0x<h>" / "0X<h>"  -> "<h>" verbatim (prefix stripped, digits unchanged)
//   <symbol>           -> the symbol's st_value as lowercase hex
// On any failure (undefined symbol, unreadable/!ELF file) returns "" and sets
// `err` to a message naming the boundary; on success leaves `err` empty.
std::string resolve_pc(const std::string& elf_path, const std::string& boundary,
                       std::string& err);

}  // namespace andes_sim

#endif  // ANDES_SIM_ELF_SYMS_HPP

// Oracle differential compare (verify_oracle F2): field-wise diff of two
// drained hybrid_state_v1 records -- the QEMU oracle's exit-boundary drain
// (ref) against the hybrid run's vsim drain (got).
//
// Compare policy, fixed by what vsim's drain freshly reads (state_drain.hpp
// drain_with_passthrough):
//   strict:  magic/version/flags/hart_id/priv (identity), pc, gpr[0..31];
//            fpr[0..31] under FLAG_FP; vstart/vtype/vl/vlenb/vxsat/vxrm/vcsr
//            and the vreg bytes under FLAG_V.
//   skipped: mstatus, mepc, mtvec, mcause, mtval, mscratch, medeleg,
//            mideleg, mip, mie, satp, pmpcfg[], pmpaddr[] -- passthrough on
//            the vsim side (copied from QEMU1's ENTRY snapshot, never
//            re-read), so comparing them would test entry-vs-exit.
//   masked:  mcycle, minstret, mcycle/minstret_at_measure_start -- the
//            engines count cycles/insns differently by design.
#ifndef ANDES_SIM_STATE_DIFF_HPP
#define ANDES_SIM_STATE_DIFF_HPP

#include <string>
#include <vector>

#include "hybrid/state_abi.h"

namespace andes_sim {

// One strictly-compared field that differs: "pc", "x5", "f31", "vl",
// "v3[7]" (register + byte offset), "flags", ...
struct FieldDiff {
  std::string field;
  unsigned long long ref = 0;
  unsigned long long got = 0;
};

struct DiffReport {
  int compared = 0;  // count of strictly compared fields
  std::vector<FieldDiff> diffs;
  bool ok() const { return diffs.empty(); }
};

DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got);

// Print `r` as "[state-diff] ..." lines: one per mismatch, then the
// PASS/FAIL verdict. Shared by the state-diff subcommand and run --verify.
void print_diff_report(const DiffReport& r);

}  // namespace andes_sim

#endif  // ANDES_SIM_STATE_DIFF_HPP

// Subprocess helpers for andes-sim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/cycle.
#ifndef ANDES_SIM_PROCESS_HPP
#define ANDES_SIM_PROCESS_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// and stderr are redirected to /dev/null. If the child runs longer than
// timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms);

// Run argv to completion with the child INHERITING this process's stdout and
// stderr (its output streams straight to the terminal) and stdin from
// /dev/null; chdir to `cwd` first if non-empty. No capture, no timeout. Returns
// the child's exit code, 128+signal if it was signalled, or -1 on spawn
// failure. Used by `build` to delegate to setup.sh / build_*.sh / make.
int run_inherit(const std::vector<std::string>& argv, const std::string& cwd);

// Run argv to completion with the child INHERITING all three std streams
// (stdin, stdout, stderr) -- the transparent-passthrough mechanism behind
// `run --model fast|cycle`: the engine reads/writes the terminal directly,
// so an interactive gdbstub or semihosting console works unchanged. No chdir,
// no capture, no timeout. Returns the child's exit code, 128+signal if it was
// signalled, or -1 on spawn failure / empty argv.
int exec_passthrough(const std::vector<std::string>& argv);

}  // namespace andes_sim

#endif  // ANDES_SIM_PROCESS_HPP

