// See elf_syms.hpp. Reads the ELF .symtab directly (no `nm` shell-out).
#include "elf_syms.hpp"

#include <cstdint>
#include <cstring>
#include <fstream>
#include <sstream>
#include <vector>

#include <elf.h>

namespace andes_sim {
namespace {

// Lowercase, minimal-width hex -- matches the bare hex a stripped "0x" address
// yields, so a symbol and its literal address resolve to the same string.
std::string to_hex(uint64_t v) {
  std::ostringstream ss;
  ss << std::hex << v;
  return ss.str();
}

bool slurp(const std::string& path, std::vector<char>& buf) {
  std::ifstream f(path, std::ios::binary);
  if (!f) return false;
  std::ostringstream ss;
  ss << f.rdbuf();
  const std::string s = ss.str();
  buf.assign(s.begin(), s.end());
  return true;
}

// memcpy a POD header out of the buffer at `off`; false if it would overrun
// (buffers may be truncated/malformed -- never read past the end).
template <class T>
bool load(const std::vector<char>& buf, size_t off, T& out) {
  if (off + sizeof(T) > buf.size()) return false;
  std::memcpy(&out, buf.data() + off, sizeof(T));
  return true;
}

}  // namespace

std::string resolve_pc(const std::string& elf_path, const std::string& boundary,
                       std::string& err) {
  err.clear();

  // A "0x"/"0X" address is used verbatim with the prefix stripped (roi.sh
  // `${boundary#0[xX]}`); the .symtab is never touched.
  if (boundary.starts_with("0x") || boundary.starts_with("0X")) {
    std::string addr = boundary.substr(2);
    if (addr.empty()) {
      err = "malformed address '" + boundary + "'";
      return "";
    }
    return addr;
  }

  std::vector<char> buf;
  if (!slurp(elf_path, buf)) {
    err = "cannot read ELF '" + elf_path + "'";
    return "";
  }

  Elf64_Ehdr eh;
  if (!load(buf, 0, eh) || std::memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0) {
    err = "not an ELF file: " + elf_path;
    return "";
  }
  if (eh.e_ident[EI_CLASS] != ELFCLASS64) {
    err = "not an RV64 (ELFCLASS64) file: " + elf_path;
    return "";
  }

  // Scan section headers for a symbol table; resolve names through its linked
  // string table (sh_link).
  for (unsigned i = 0; i < eh.e_shnum; ++i) {
    Elf64_Shdr sym_sh;
    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
      break;
    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;

    Elf64_Shdr str_sh;
    if (sym_sh.sh_link >= eh.e_shnum ||
        !load(buf, eh.e_shoff + static_cast<size_t>(sym_sh.sh_link) * eh.e_shentsize,
              str_sh))
      continue;

    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
    for (size_t s = 0; s < nsym; ++s) {
      Elf64_Sym sym;
      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
      if (sym.st_shndx == SHN_UNDEF) continue;  // --defined-only

      const size_t noff = str_sh.sh_offset + sym.st_name;
      if (noff >= buf.size()) continue;
      const char* name = buf.data() + noff;
      const size_t avail = buf.size() - noff;
      if (::strnlen(name, avail) == avail) continue;  // unterminated in bounds
      if (boundary == name) return to_hex(sym.st_value);
    }
  }

  err = "symbol '" + boundary + "' not defined in " + elf_path;
  return "";
}

}  // namespace andes_sim

// andes-sim command-line parsing.
//
// The grammar is deliberately tiny and stable across all subcommands:
//
//   andes-sim <cmd> [--model M] [--engine E] [--trigger T] [positional...]
//                   [-- <verbatim engine args...>]
//
// The single most important rule is the `--` boundary: every token after the
// first `--` is captured verbatim into `passthrough` and is NOT interpreted by
// the framework. That is what lets `fast`/`cycle` forward an engine's whole
// native CLI (e.g. `-gdb tcp::1234 -S`) untouched, so users see one simulator.
#ifndef ANDES_SIM_CLI_HPP
#define ANDES_SIM_CLI_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct Cli {
  std::string subcommand;                 // e.g. "run", "list"; "" if none
  std::string model;                      // --model fast|cycle|hybrid
  std::string engine;                     // --engine <id>
  std::string trigger;                    // --trigger marker|pc|icount|simpoint
  std::string what;                       // --what <target> (build)
  // Hybrid trigger args (empty => cmd_run applies the default). pc boundaries
  // are a symbol name or 0x address; the icounts/sizes stay strings here and
  // are parsed where they are used.
  std::string pc_start;                   // --pc-start (trigger pc)
  std::string pc_end;                     // --pc-end   (trigger pc)
  std::string qemu_icount;                // --qemu-icount (trigger icount)
  std::string vsim_icount;                // --vsim-icount (trigger icount)
  std::string mem_size;                   // --mem-size (guest memory; --mmap-size is a hidden alias)
  std::string vsim_warmup_icount;         // --vsim-warmup-icount (vsim leg)
  std::string kanata;                     // --kanata <file> (marker/pc ROI trace)
  std::string objdump;                    // --objdump <file> (kanata labels)
  std::vector<std::string> positional;    // non-flag framework args
  std::vector<std::string> passthrough;   // verbatim, everything after `--`
  std::string cosim_interval;             // --cosim-interval (run --cosim)
  bool help = false;                      // -h / --help (before `--`)
  bool dry_run = false;                   // --dry-run (build, run, test, ...)
  bool verify = false;                    // --verify (run --model hybrid)
  bool cosim = false;                     // --cosim (run --model hybrid, dev)
  bool has_passthrough = false;           // a `--` boundary was present
  std::string error;                      // non-empty => parse failed
};

// Parse argv[1..] (program name skipped). The vector overload is the testable
// core; the argv overload adapts it for main().
Cli parse_cli(const std::vector<std::string>& args);
Cli parse_cli(int argc, char** argv);

}  // namespace andes_sim

#endif  // ANDES_SIM_CLI_HPP

